 <body>
   <main class="card">
     <h1>Notification settings</h1>
     <p>Choose the option that best matches how you'd like to stay updated.</p>

     <form id="notification-form">
       <div class="form-field">
         <p class="question">How do you prefer to receive notifications?</p>
         <div class="options" role="radiogroup" aria-label="How do you prefer to receive notifications?">
           <label class="option">
             <input type="radio" name="notification" value="Email" required />
             <span>Email</span>
           </label>
           <label class="option">
             <input type="radio" name="notification" value="SMS" />
             <span>SMS</span>
           </label>
           <label class="option">
             <input type="radio" name="notification" value="Push Notifications" />
             <span>Push Notifications</span>
           </label>
         </div>
       </div>

